import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('getisord_no2_Q1_2022.csv')
adjacency = pd.read_csv('borough_adjacency.csv')

# Handle missing values
citywide_avg = df['avg_no2_value'].dropna().mean()
df['avg_no2_value'] = df['avg_no2_value'].fillna(citywide_avg)

# Create a dictionary of neighboring boroughs
neighborhoods = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate the combined NO2 value for each borough and its neighbors
combined_values = {}
for borough, neighbors in neighborhoods.items():
    combined_values[borough] = df.loc[df['borough'] == borough, 'avg_no2_value'].values[0] + sum(df.loc[df['borough'].isin(neighbors), 'avg_no2_value'].values)

# Calculate the citywide average combined NO2 value
citywide_avg_combined = combined_values.values().mean()

# Calculate the standard deviation of the combined NO2 values
std_dev_combined = np.std(combined_values.values())

# Calculate the z-score for each borough
z_scores = {}
for borough, value in combined_values.items():
    z_scores[borough] = (value - citywide_avg_combined) / std_dev_combined

# Identify hot and cold spots
hot_spots = {borough: z_score for borough, z_score in z_scores.items() if abs(z_score) > 1.96}
cold_spots = {borough: z_score for borough, z_score in z_scores.items() if abs(z_score) > 1.96 and z_score < 0}

# Exclude boroughs with missing values
hot_spots = {borough: z_score for borough, z_score in hot_spots.items() if not pd.isna(df.loc[df['borough'] == borough, 'avg_no2_value'].values[0])}
cold_spots = {borough: z_score for borough, z_score in cold_spots.items() if not pd.isna(df.loc[df['borough'] == borough, 'avg_no2_value'].values[0])}

# Print the results
data_points_used = len(combined_values)
results = []
for borough, z_score in hot_spots.items():
    results.append(f'{borough} (HOT, Gi*={z_score:.4f})')
for borough, z_score in cold_spots.items():
    results.append(f'{borough} (COLD, Gi*={z_score:.4f})')
print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: {", ".join(results)}')

import pandas as pd
import numpy as np

# Load the data
borough_data = pd.read_csv('chunks_csv/getisord/getisord_no2_Q1_2022.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Calculate the citywide average NO2 value
citywide_avg = borough_data['avg_no2_value'].mean()

# Replace missing values in the avg_no2_value column with the citywide average
borough_data['avg_no2_value'] = borough_data['avg_no2_value'].fillna(citywide_avg)

# Create a dictionary of neighboring boroughs
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate the combined NO2 value for each borough and its neighbors
combined_values = {}
for index, row in borough_data.iterrows():
    combined_value = row['avg_no2_value']
    for neighbor in neighborhoods[row['borough']]:
        combined_value += borough_data.loc[borough_data['borough'] == neighbor, 'avg_no2_value'].values[0]
    combined_values[row['borough']] = combined_value

# Calculate the citywide average combined NO2 value
citywide_avg_combined = np.mean(list(combined_values.values()))

# Calculate the standard deviation of the combined NO2 values
std_dev_combined = np.std(list(combined_values.values()))

# Calculate the z-score for each borough
z_scores = {}
for borough, combined_value in combined_values.items():
    z_score = (combined_value - citywide_avg_combined) / std_dev_combined
    z_scores[borough] = z_score

# Identify hot and cold spots
hot_spots = {borough: z_score for borough, z_score in z_scores.items() if np.abs(z_score) > 1.96}
cold_spots = {borough: z_score for borough, z_score in z_scores.items() if np.abs(z_score) > 1.96 and z_score < 0}

# Exclude boroughs with missing values
hot_spots = {borough: z_score for borough, z_score in hot_spots.items() if not np.isnan(borough_data.loc[borough_data['borough'] == borough, 'avg_no2_value'].values[0])}
cold_spots = {borough: z_score for borough, z_score in cold_spots.items() if not np.isnan(borough_data.loc[borough_data['borough'] == borough, 'avg_no2_value'].values[0])}

# Print the results
data_points_used = len(borough_data)
results = []
for borough, z_score in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={z_score})")
for borough, z_score in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={z_score})")
print(f"data_points_used = {data_points_used}")
if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
